<script>
  // @ts-nocheck
  import { onMount } from 'svelte'; import BotonVolver from '$lib/componentes/BotonVolver.svelte'; import { pedirApi } from '$lib/api.js'; import { fmtPesos } from '$lib/formato.js';
  let facturas=$state([]);let negocio=$state(null);let error=$state('');onMount(async()=>{try{[facturas,negocio]=await Promise.all([pedirApi('/api/facturas'),pedirApi('/api/negocio')])}catch(e){error=e.message}});
</script>
<BotonVolver /><h2>Facturación</h2><p class="text-muted">Comprobantes internos emitidos hoy.</p>{#if error}<p class="error">{error}</p>{/if}<div class="dos"><section class="card tabla"><table class="table"><thead><tr><th>Factura</th><th>Hora</th><th>Total</th><th></th></tr></thead><tbody>{#each facturas as f}<tr><td>{f.factura}</td><td>{f.hora}</td><td>{fmtPesos(f.total_venta)}</td><td><button class="btn btn-ghost" onclick={()=>window.print()}>Imprimir</button></td></tr>{/each}</tbody></table>{#if !facturas.length}<p class="text-muted">Todavía no hay facturas emitidas hoy.</p>{/if}</section>{#if negocio}<section class="card"><span class="card-kicker">Datos del negocio</span><h4>{negocio.nombre_negocio}</h4><span>{negocio.cuit || 'CUIT sin cargar'}</span><span class="text-muted">{negocio.direccion || 'Dirección sin cargar'}</span><span>Punto de venta {negocio.punto_venta}</span></section>{/if}</div><style>.dos{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-top:18px}.tabla{padding:4px}.error{color:var(--color-peligro)}</style>
